window.RP_SESSION={"id":"S-f6b1092b0701","messages":[{"id":"RP-III-0110548","time":"2026-06-05T13:36:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"얼마 전에 의뢰를 나갔다가 실버 대신 사슴 다리 두 짝을 받아 왔습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110549","time":"2026-06-05T13:38:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"가죽은 벗겨서 가공중이고, 살은 갓 분리해서 일부는 바로 먹을 고기로, 일부는 보관용으로 분리했고, 힘줄 등도 다 해체하고...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110550","time":"2026-06-05T13:38:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"남은건 뼈.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110551","time":"2026-06-05T13:38:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"당연히 버리기는 너무 아깝습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110552","time":"2026-06-05T13:38:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110553","time":"2026-06-05T13:38:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 힘 판정 :\n[10] + [1] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-III-0110554","time":"2026-06-05T13:39:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"무겁고 커다란 칼을 들고 커다란 뼈들을 가로로 한 번, 세로로 한 번 쪼갭니다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110555","time":"2026-06-05T13:39:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"반원형으로 만들어진 다리뼈들이 몇 개 나옵니다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110556","time":"2026-06-05T13:42:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"다리뼈의 골수를 위로 가게 해서 골수에 소금과 코리앤더 씨앗, 다진 마늘을 골고루 뿌려 금속 트레이에 넣고 화덕에 넣어 굽는 동안, 부엌에 있던 바게트 빵을 자르고.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110557","time":"2026-06-05T13:43:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"양파는 썰어 물에 담가 두고, 먹기 좋게 자른 파슬리와 다진 마늘, 레몬즙, 케이퍼, 소금, 코리앤더 씨앗, 올리브 오일을 나무 볼에 담고, 물에 담가뒀던 양파를 넣어 샐러드를 만든다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110558","time":"2026-06-05T13:44:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"바로 먹으려고 빼둔 사슴 살코기를 굽고, 골수가 다 익자 골수를 트레이에서 빼고 트레이에 남은 소기름에 바게트 빵을 적셔 오븐에 데운다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110559","time":"2026-06-05T13:45:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"커다란 나무 접시에 담아 합치면...!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110560","time":"2026-06-05T14:03:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"레마, 또 요리해? 오늘은 뭐야?\"","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0110561","time":"2026-06-05T14:04:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 사슴 고, 골수 요리! 와서 먹어봐. \"\n\n커다랗게 반원형으로 잘라 구운 사슴 뼈와 썰린 바게트, 샐러드, 기름기 없는 사슴 고기가 담긴 접시.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110562","time":"2026-06-05T14:37:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"응!\"\n레마가 만든 요리 한입 먹는다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0110563","time":"2026-06-05T14:42:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어때? \"\n\n마치 버터처럼 고소한 골수가 재료들과 만나 지방과 기름짐을 더한다. 적절히 들어간 향신료들이 시너지를 내서 맛있게 즐길 수 있는 식사가 된다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110564","time":"2026-06-05T14:47:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"역시 레마야, 이것도 너무 맛있다!\"\n순식간에 한그릇 다 비운다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0110565","time":"2026-06-05T14:49:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 후후, 멜리아를 위, 위해서라면 언제든지 만들어 주, 줄 수 있지! \"\n\n멜리아의 좋은 반응을 보고 뿌듯해진 레마!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110566","time":"2026-06-05T14:59:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"항상 고마워! 헤헤...\"","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0110567","time":"2026-06-05T15:02:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 이것도 버리기엔 아, 아깝지. \"\n\n금새 다 먹고 남은 구운 뼈는 솥에 넣어 물과 약간의 맥주를 넣고 삶기 시작한다. 그리고 뒷정리 설거지를 하며.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110568","time":"2026-06-05T15:03:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"저 뼈로는 뭐 만들 거야?\"\n옆에서 설거지 도우려 한다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0110569","time":"2026-06-05T15:05:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 뼈를 푹 고, 고아서 스튜 베이스로 마, 만들거야! \"\n\n설거지를 끝내고 솥을 한 번 휘 저으며.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110570","time":"2026-06-05T15:15:00+09:00","room":"RP III","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"그것도 기대할게!\"\n같이 설거지 도와 끝내고 자리에 앉는다.","characters":["P-5401fadc6bc3"]},{"id":"RP-III-0110571","time":"2026-06-05T18:02:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fec1db60d51e"]},{"id":"RP-III-0110572","time":"2026-06-05T18:02:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
